<?php
require_once __DIR__.'/../bootstrap.php';$user=requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Método no permitido.',405);$d=jsonBody();$cliente=filter_var($d['cliente_id']??null,FILTER_VALIDATE_INT);$sucursal=filter_var($d['sucursal_id']??null,FILTER_VALIDATE_INT);$fecha=(string)($d['fecha']??'');$detalle=requiredText($d,'detalle',500);$total=filter_var($d['total']??null,FILTER_VALIDATE_FLOAT);if(!$cliente||!$sucursal)fail('Seleccioná un cliente y una sucursal.',422);$dt=DateTime::createFromFormat('!Y-m-d',$fecha);if(!$dt||$dt->format('Y-m-d')!==$fecha)fail('La fecha debe tener formato YYYY-MM-DD.',422);if($total===false||$total<=0||$total>999999999)fail('El total debe ser mayor que cero.',422);$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id FROM clientes WHERE id=?');$q->execute([$cliente]);if(!$q->fetch())throw new DomainException('Cliente inexistente.');$q=$pdo->prepare('SELECT id FROM sucursales WHERE id=? AND activa=1');$q->execute([$sucursal]);if(!$q->fetch())throw new DomainException('Sucursal inexistente.');$num='NC-'.date('Ymd',strtotime($fecha)).'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare('INSERT INTO ventas(numero_factura,fecha,cliente_id,sucursal_id,total,creado_por) VALUES(?,?,?,?,?,?)');$st->execute([$num,$fecha,$cliente,$sucursal,$total,$user['id']]);$id=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO venta_detalles(venta_id,descripcion,cantidad,precio_unitario,subtotal) VALUES(?,?,1,?,?)');$line->execute([$id,$detalle,$total,$total]);$pdo->commit();respond(['id'=>$id,'numero_factura'=>$num],201);}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();fail($e->getMessage(),422);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
